from pathlib import Path
import json

def run_suite(eval_path: Path, runner) -> dict:
    cases = json.loads(eval_path.read_text())
    passed = 0
    failures = []
    for case in cases:
        actual = runner(case["input"])
        if actual.category == case["expected_category"]:
            passed += 1
        else:
            failures.append((case["id"], case["expected_category"], actual.category))
    return {"total": len(cases), "passed": passed, "failures": failures}

