def compute_eval_metrics(records: list[dict]) -> dict:
    total = len(records)
    if total == 0:
        return {}
    schema_ok = sum(1 for r in records if r["valid_schema"])
    recall_at_5 = sum(
        1 for r in records if r["gold_doc_id"] in r["retrieved_doc_ids"][:5]
    )
    urgent = [r for r in records if r["gold_category"] == "urgent_outage"]
    urgent_recall = (
        sum(1 for r in urgent if r["pred_category"] == "urgent_outage") / len(urgent)
        if urgent else 1.0
    )
    return {
        "schema_pass_rate": round(schema_ok / total, 3),
        "retrieval_recall_at_5": round(recall_at_5 / total, 3),
        "urgent_outage_recall": round(urgent_recall, 3),
    }

from pydantic import BaseModel

class JudgeVerdict(BaseModel):
    grounded_in_policy: bool
    polite_and_concise: bool
    reason: str

def evaluate_draft(case: dict, output: dict, run_judge) -> dict:
    # 1. Deterministic invariants (fast, exact, zero cost):
    det_checks = {
        "valid_category": output["category"] == case["expected_category"],
        "valid_citations": set(output["cited_ids"]).issubset(set(output["retrieved_ids"])),
        "no_forbidden_promise": "guaranteed refund" not in output["draft"].lower(),
    }
    if not all(det_checks.values()):
        return {"passed": False, "deterministic": det_checks, "judge": None}

    # 2. Focused binary judge rubric ONLY after deterministic checks pass:
    verdict: JudgeVerdict = run_judge(policy=case["policy_text"], draft=output["draft"])
    return {
        "passed": verdict.grounded_in_policy and verdict.polite_and_concise,
        "deterministic": det_checks,
        "judge": verdict.model_dump(),
    }

def diff_eval_runs(baseline: dict[str, bool], candidate: dict[str, bool]) -> dict:
    regressions = [
        cid for cid, passed in baseline.items()
        if passed and not candidate.get(cid, False)
    ]
    improvements = [
        cid for cid, passed in candidate.items()
        if passed and not baseline.get(cid, False)
    ]
    return {
        "baseline_score": sum(baseline.values()) / len(baseline),
        "candidate_score": sum(candidate.values()) / len(candidate),
        "regressions": regressions,
        "improvements": improvements,
    }

import json
import logging
import time
from typing import Any

class JsonFormatter(logging.Formatter):
    def format(self, record: logging.LogRecord) -> str:
        payload: dict[str, Any] = {
            "ts": self.formatTime(record, "%Y-%m-%dT%H:%M:%SZ"),
            "level": record.levelname,
            "logger": record.name,
            "message": record.getMessage(),
        }
        extra = getattr(record, "fields", None)
        if isinstance(extra, dict):
            payload.update(extra)
        if record.exc_info:
            payload["exception"] = self.formatException(record.exc_info)
        return json.dumps(payload, default=str)

def log_step(logger: logging.Logger, step: str, request_id: str, duration_ms: float, **fields: Any) -> None:
    logger.info(
        f"step={step}",
        extra={"fields": {"step": step, "request_id": request_id, "duration_ms": round(duration_ms, 2), **fields}},
    )

import contextvars
import time
from contextlib import contextmanager

trace_id_var: contextvars.ContextVar[str] = contextvars.ContextVar("trace_id", default="unset")

@contextmanager
def trace_span(step_name: str, logger, **attrs):
    start = time.perf_counter()
    status = "ok"
    try:
        yield
    except Exception as exc:
        status = f"error:{type(exc).__name__}"
        raise
    finally:
        elapsed_ms = round((time.perf_counter() - start) * 1000, 2)
        logger.info(
            "span",
            extra={
                "fields": {
                    "trace_id": trace_id_var.get(),
                    "span": step_name,
                    "duration_ms": elapsed_ms,
                    "status": status,
                    **attrs,
                }
            },
        )

from dataclasses import dataclass

@dataclass(frozen=True)
class ModelRate:
    input_per_1m_usd: float
    output_per_1m_usd: float

def compute_call_cost_usd(
    *,
    input_tokens: int,
    output_tokens: int,
    rate: ModelRate,
) -> float:
    in_cost = (max(0, input_tokens) / 1_000_000) * rate.input_per_1m_usd
    out_cost = (max(0, output_tokens) / 1_000_000) * rate.output_per_1m_usd
    return round(in_cost + out_cost, 6)

def inspect_confidence_calibration(eval_results: list[dict], threshold: float = 0.90) -> dict:
    high_conf = [r for r in eval_results if r["model_confidence"] >= threshold]
    if not high_conf:
        return {"count": 0, "actual_precision": None}
    actually_right = sum(1 for r in high_conf if r["is_correct"])
    return {
        "threshold": threshold,
        "cases_above_threshold": len(high_conf),
        "actual_precision": round(actually_right / len(high_conf), 3),
        # If threshold=0.90 yields actual_precision=0.72, DO NOT auto-send!
    }

