def is_safe_inbound_ticket(sender: str, headers: dict[str, str], support_addr: str) -> bool:
    if sender.lower() == support_addr.lower():
        return False  # Never process emails sent by our own support system!
    for k, bad_val in AUTO_SKIP_HEADERS.items():
        if headers.get(k, "").lower() == bad_val:
            return False  # Skip OOO / vacation auto-responders!
    return True

